import{_ as a,a as i,b as t,c as r,d as s,e as l,f as n,g as o,h as p,i as c}from"./chunks/CAL11.DuBx0sYj.js";import{_ as u}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as d}from"./chunks/BDM.scaBLLhv.js";import{_ as m,o as b,c as v,a3 as g}from"./chunks/framework.g9mfNVRQ.js";const L=JSON.parse('{"title":"Calibrer","description":"","frontmatter":{"source_hash":"b31e419e7a","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/calibrate/calibrate.md","filePath":"fr/calibrate/calibrate.md"}'),h={name:"fr/calibrate/calibrate.md"};function f(x,e,q,z,_,y){return b(),v("div",null,[...e[0]||(e[0]=[g('<div class="warning custom-block"><p class="custom-block-title">Étalonnage</p><p>Ne faites jamais aveuglément confiance à un capteur de glucose : vérifiez régulièrement les valeurs par une glycémie capillaire.<br> Une ligne plate (toujours la même valeur) n&#39;est <strong>jamais</strong> bon signe.</p></div><h3 id="general-considerations" tabindex="-1">Considérations générales <a class="header-anchor" href="#general-considerations" aria-label="Permalink to &quot;Considérations générales {#general-considerations}&quot;">​</a></h3><p>L&#39;étalonnage est essentiel à la précision des mesures du CGM. Utilisez toujours un lecteur de glycémie fiable et placez-vous dans les meilleures conditions pour obtenir la mesure capillaire la plus précise possible au moment d&#39;étalonner.</p><p>Parmi les prérequis les plus importants :</p><ol><li><strong>Glycémie stable.</strong> N&#39;étalonnez jamais lorsque la glycémie monte ou descend rapidement.</li><li><strong>Dans la cible (important pour l&#39;étalonnage initial du Libre).</strong> Essayez d&#39;étalonner lorsque la glycémie est dans la plage normale (80-180 mg/dl ou 5-10 mmol/l).</li><li><strong>N&#39;étalonnez pas trop.</strong> Mieux vaut quelques étalonnages précis que trop nombreux : vous risquez fort d&#39;embrouiller xDrip. Pour les G6, G7, ONE, ONE+, suivez les recommandations du fabricant.</li></ol><h3 id="native-and-xdrip-algorithms" tabindex="-1">Algorithmes natif et xDrip <a class="header-anchor" href="#native-and-xdrip-algorithms" aria-label="Permalink to &quot;Algorithmes natif et xDrip {#native-and-xdrip-algorithms}&quot;">​</a></h3><p>xDrip peut appliquer ses propres algorithmes de calibration aux capteurs qui envoient des données brutes.</p><p>La calibration native des G6, G7, ONE, ONE+ signifie que xDrip n&#39;utilise pas son algorithme : il envoie les valeurs de calibration à l&#39;émetteur et le laisse les traiter avec son propre algorithme propriétaire.</p><p>Les capteurs Libre 1, 14 jours, Pro, 2 (EU) et 2+ (EU) n&#39;envoient que des données brutes et ont besoin soit de la calibration xDrip, soit d&#39;un plugin de calibration externe appelé <a href="./../use/OOP.html">algorithme hors processus</a> (OOP en abrégé).</p><p>L&#39;application patchée du Libre 2 utilise son propre algorithme propriétaire (une ancienne version, toutefois).</p><table tabindex="0"><thead><tr><th>Capteur</th><th>Calibration xDrip</th><th>Calibration native</th></tr></thead><tbody><tr><td>G6 avec pile remplacée</td><td>Disponible</td><td>Disponible</td></tr><tr><td>G6, G7, ONE, ONE+</td><td>Non disponible</td><td>Obligatoire</td></tr><tr><td>Libre 1</td><td>Obligatoire</td><td>OOP1 (obsolète)</td></tr><tr><td>Libre 2 EU application patchée</td><td>Décalage limité (voir ci-dessous)</td><td>Par conception</td></tr><tr><td>Libre 2/2+ EU, Libre 14 jours US</td><td><a href="./../use/OOP.html#oop2">Facultative</a></td><td>OOP2</td></tr></tbody></table><h5 id="libre-2-patched-app" tabindex="-1">Application patchée Libre 2 <a class="header-anchor" href="#libre-2-patched-app" aria-label="Permalink to &quot;Application patchée Libre 2 {#libre-2-patched-app}&quot;">​</a></h5><p>Avec l&#39;application patchée, vous pouvez étalonner, mais la correction est appliquée comme un décalage, dans la limite de -40 mg/dl à +20 mg/dL [-2,2 mmol/l à +1,1 mmol/l]. Les calibrations hors de ces limites sont <strong>ignorées</strong>.</p><h3 id="xdrip-calibration-settings" tabindex="-1">Paramètres de calibration de xDrip <a class="header-anchor" href="#xdrip-calibration-settings" aria-label="Permalink to &quot;Paramètres de calibration de xDrip {#xdrip-calibration-settings}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Calibration xDrip uniquement</p><p>Les informations ci-dessous concernent la calibration xDrip.<br> Pour le mode natif G6/G7/ONE/ONE+, voir <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">ici</a>.</p></div><p>Avant d&#39;étalonner, vérifiez vos <a href="./advancedcal.html">paramètres</a>.</p><p>Une option à activer est l&#39;affichage des <a href="./../use/lesscommon.html#show-data-tables">tables de données</a> dans le menu principal. Elle aide vraiment à comprendre ce qui se passe quand les choses tournent mal.</p><h3 id="first-calibration" tabindex="-1">Premier étalonnage <a class="header-anchor" href="#first-calibration" aria-label="Permalink to &quot;Premier étalonnage {#first-calibration}&quot;">​</a></h3><p>Si votre capteur nécessite des calibrations, une fois qu&#39;il est connecté à xDrip et que trois valeurs ont été reçues, cette demande devrait s&#39;afficher :</p><div class="admonition xdripitem"><p class="admonition-title">Calibrer le capteur?</p><p> Nous avons quelques valeurs!</p><p> Ensuite, nous avons besoin d&#39;un premier test de glycémie capillaire.</p><p> Prêt à calibrer maintenant ?</p><p> NON    <span style="background-color:white;color:black;"> CALIBRER </span></p></div><p>Les deux valeurs d&#39;étalonnage initial sont un héritage du G4. Pour les utiliser correctement, faites deux mesures différentes (deux bandelettes) : c&#39;est l&#39;approche recommandée. Si vous saisissez habituellement la même valeur, vous pouvez en faire le comportement par défaut <a href="./advancedcal.html#calibrations">ici</a>.</p><div class="admonition xdrip"><p class="admonition-title">☰ Étalonnage initial</p><p> <u>Entrer la première valeur de glycémie</u><br>  <u>Entrer la seconde valeur de glycémie</u></p><p> <small>Pour pouvoir commencer, effectuer deux tests de glycémie capillaire et entrer les valeurs ici!</small></p></div><p>Si vous utilisez la calibration native, la valeur est envoyée à l&#39;émetteur pour être traitée.</p><p>Si vous utilisez la calibration xDrip, cette valeur est traitée 10 minutes plus tard afin de compenser tous les retards physiologiques et chimiques de la mesure du CGM : <strong>c&#39;est pourquoi il est extrêmement important d&#39;étalonner à glycémie stable</strong>.</p><p>Voyons graphiquement ce qui se passe sur l&#39;écran principal :</p><ol><li>Première valeur (ramenée à la valeur de calibration)</li><li>Deuxième valeur (ramenée à la valeur de calibration)</li><li>Pas encore visible, mais c&#39;est la troisième valeur : la valeur réelle au moment où vous avez étalonné</li><li>Valeur suivante dans 5 minutes</li><li>Valeur suivante dans 10 minutes et point de calibration (qui sera utilisé dans 10 minutes)</li></ol><img src="'+a+'"><p>Si votre glycémie est restée stable pendant ce temps, vous devriez voir la courbe passer par le point de calibration.</p><img src="'+i+'"><p>Dans votre tableau de calibrations, vous verrez de nouvelles entrées correspondant aux mesures brutes utilisées pour définir la calibration :</p><ol><li>La valeur que vous avez saisie (convertie si nécessaire en mg/dl)</li><li>La même valeur dans l&#39;unité que vous utilisez dans xDrip (ici en mg/dl, mais elle s&#39;affiche aussi en mmol/l)</li><li>La glycémie brute du capteur</li><li>La pente et l&#39;ordonnée à l&#39;origine calculées</li><li>La date et l&#39;heure effectives de la calibration (soit l&#39;heure réelle + 10 minutes) et la date et l&#39;heure de la mesure brute correspondante</li><li>Il y a deux jeux de mesures brutes pour une calibration : un plus bas, un plus haut</li></ol><img src="'+t+'" style="zoom:75%;"><p>Votre graphe de calibration ressemble maintenant à ceci.<br> Selon l&#39;écart entre les échantillons sanguins et la variabilité de la glycémie du moment, la pente n&#39;est pas forcément exactement 1.</p><img src="'+r+'" style="zoom:75%;"><h3 id="successive-calibrations" tabindex="-1">Étalonnages suivants <a class="header-anchor" href="#successive-calibrations" aria-label="Permalink to &quot;Étalonnages suivants {#successive-calibrations}&quot;">​</a></h3><p>Par sécurité, vous vérifierez régulièrement votre glycémie réelle, au moins une fois par jour, car vous ne pouvez pas faire aveuglément confiance à un capteur. Saisissez ces glycémies capillaires comme <a href="./../use/mainUI.html#treatments">traitements</a>.<br> Pour avoir des glycémies qui ne varient pas trop vite, n&#39;étalonnez pas lorsque des glucides ou de l&#39;insuline sont actifs à ce moment-là.</p><div class="info custom-block"><p class="custom-block-title">Fréquence</p><p>À moins que votre capteur ne l&#39;exige expressément, n&#39;étalonnez pas systématiquement à chaque glycémie capillaire.<br> Pour les capteurs Libre, il n&#39;est pas forcément nécessaire d&#39;étalonner si l&#39;écart est inférieur à 15 %.</p></div><p><strong>N&#39;étalonnez pas trop</strong> : vous pouvez faire autant de glycémies capillaires que vous le souhaitez et les saisir comme traitements dans xDrip, mais ajoutez des calibrations avec beaucoup de précaution.</p><p>Sur votre graphe de calibration, les points de calibration actifs apparaissent en bleu, les anciens ou invalides en gris.</p><img src="'+s+'" style="zoom:75%;"><p>Si, à glycémie stable, la valeur de xDrip 10 minutes après votre glycémie capillaire s&#39;en écarte trop, ajoutez un nouveau point de calibration.</p><p>Comme l&#39;évolution de la glycémie est souvent difficile à prévoir, vous pouvez utiliser une astuce :</p><ul><li>Vérifiez que Utiliser les valeurs BG des traitements n&#39;est pas réglé sur Never use them dans <a href="./advancedcal.html">Calibration avancée</a>.</li><li>Saisissez votre glycémie capillaire comme traitement.</li></ul><img src="'+l+'" style="zoom:75%;"><ul><li>Attendez 10 minutes et jugez si c&#39;était un bon moment pour étalonner (assez stable).</li></ul><img src="'+n+'" style="zoom:75%;"><ul><li>Si c&#39;était le cas, appuyez sur votre traitement (la nouvelle glycémie capillaire, point carré blanc sur le graphique) et transformez-le en calibration.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Action de test sanguin</p><p> Que voulez-vous faire?</p><p> RIEN EFFACER   <span style="background-color:white;color:black;"> CALIBRER </span></p></div><p>Vous avez maintenant un point de calibration supplémentaire.</p><img src="'+o+'" style="zoom:75%;"><h3 id="disable-a-calibration" tabindex="-1">Désactiver une calibration <a class="header-anchor" href="#disable-a-calibration" aria-label="Permalink to &quot;Désactiver une calibration {#disable-a-calibration}&quot;">​</a></h3><p>Il peut arriver qu&#39;un point de calibration soit manifestement mauvais et que vous vouliez le supprimer.</p><p>Ouvrez le Tableau de calibrations et faites un <strong>appui long</strong> sur la calibration à désactiver.</p><img src="'+p+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Disable this calibration?</p><p>Flagged calibrations will no longer have an effect.</p><p>   NON    <span style="background-color:white;color:black;"> OUI </span></p></div><p>Elle s&#39;affiche en rouge et n&#39;est plus utilisée dans les calculs.</p><img src="'+c+'" style="zoom:75%;"><h3 id="reset-all-calibrations" tabindex="-1">Réinitialiser toutes les calibrations <a class="header-anchor" href="#reset-all-calibrations" aria-label="Permalink to &quot;Réinitialiser toutes les calibrations {#reset-all-calibrations}&quot;">​</a></h3><p>Cette méthode ne s&#39;applique qu&#39;aux capteurs compatibles avec la calibration xDrip.</p><p><strong>Ne l&#39;utilisez pas pour les capteurs à calibration native uniquement (G6 récent, G7, ONE, ONE+, etc.).</strong></p><p>Le moyen le plus rapide de reprendre l&#39;étalonnage à zéro (Calibration initiale), lorsqu&#39;il devient évident que les calibrations actuelles sont fausses ou que vous n&#39;avez pas de données après avoir étalonné, est de réinitialiser toutes les calibrations.</p><p>Dans le menu principal, choisissez Arrêter le capteur.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+u+'" style="zoom:75%;"></p><p> Arrêter le capteur</p></div><p><strong>N&#39;arrêtez pas le capteur</strong> : réinitialisez seulement toutes les calibrations.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+d+'" style="zoom:75%;"> Arrêt du capteur <span class="symbol"></span></p><p> N&#39;arrêtez votre capteur que lorsque vous planifiez de l&#39;enlever, sinon laissez fonctionner!</p><p>       <span style="background-color:white;color:black;"> NE PAS ARRÊTER, SIMPLEMENT RÉINITIALISER LES CALIBRATIONS </span></p></div><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Voulez-vous supprimer et réinitialiser les calibrations de ce capteur ?</p><p>       NON    <span style="background-color:white;color:black;"> OUI </span></p></div><p>xDrip vous ramène alors à l&#39;<a href="#first-calibration">étalonnage initial</a>. Veillez à effectuer cette opération à glycémie stable, dans la cible.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',69)])])}const O=m(h,[["render",f]]);export{L as __pageData,O as default};
